{constructor, attribute, type?, type_option?} =
  case attribute do
    %{name: "updated_at", attr_type: attr_type} ->
      {"update_timestamp", %{attribute | default: nil, generated?: false}, false,
       attr_type != :utc_datetime_usec}

    %{default: default, attr_type: attr_type}
    when default == now_default ->
      {"create_timestamp", %{attribute | default: nil, generated?: false}, false,
       attr_type != :utc_datetime_usec}

    %{default: default, attr_type: attr_type, primary_key?: true}
    when default == uuid_default ->
      {"uuid_primary_key",
       %{
         attribute
         | default: nil,
           primary_key?: false,
           generated?: false,
           allow_nil?: true
       }, false, attr_type != :uuid}

    _ ->
      {"attribute", attribute, true, false}
  end

%{migration_default: "CURRENT_TIMESTAMP"} ->
  %{attribute | default: &DateTime.utc_now/0}

%{migration_default: "now()"} ->
  %{attribute | default: &DateTime.utc_now/0}

%{migration_default: "(now() AT TIME ZONE 'utc'::text)"} ->
  %{attribute | default: &DateTime.utc_now/0}

%{migration_default: "gen_random_uuid()"} ->
  %{attribute | default: &Ash.UUID.generate/0}

%{migration_default: "uuid_generate_v4()"} ->
  %{attribute | default: &Ash.UUID.generate/0}

%{attr_type: :integer, migration_default: value} ->
  case Integer.parse(value) do
    {value, ""} ->
      %{attribute | default: value}

    _ ->
      attribute
  end

%{attr_type: :decimal, migration_default: value} ->
  case Decimal.parse(value) do

            type :: :custom | :exclusion | :unique | :foreign | :check,
            name :: String.t()
          ) ::
            :exact | :prefix | :suffix | {:regex, Regex.t()}

@doc "Allows overriding a given migration type for *all* fields, for example if you wanted to always use :timestamptz for :utc_datetime fields"
@callback override_migration_type(atom) :: atom
@doc "Whether or not to use the built-in `uuidv7` function (as opposed to the Ash `uuid_generate_v7` function) for `UUIDv7` fields."
@callback use_builtin_uuidv7_function? :: boolean
@doc "Should the repo should be created by `mix ash_postgres.create`?"
@callback create?() :: boolean
@doc "Should the repo should be dropped by `mix ash_postgres.drop`?"
@callback drop?() :: boolean

@doc "Disable atomic actions for this repo"
@callback disable_atomic_actions?() :: boolean

@doc "Disable expression errors for this repo"
@callback disable_expr_error?() :: boolean

@doc """

    "index [\"column\", \"column2\"], unique: true, where: \"thing = TRUE\""
  ],
  target: AshPostgres.CustomIndex,
  schema: AshPostgres.CustomIndex.schema(),
  transform: {AshPostgres.CustomIndex, :transform, []},
  args: [:fields]
}

@custom_indexes %Spark.Dsl.Section{
  name: :custom_indexes,
  describe: """
  A section for configuring indexes to be created by the migration generator.

  In general, prefer to use `identities` for simple unique constraints. This is a tool to allow
  for declaring more complex indexes.
  """,
  examples: [
    """
    custom_indexes do
      index [:column1, :column2], unique: true, where: "thing = TRUE"
    end
    """
  ],
  entities: [
    @index
  ]
}

@statement %Spark.Dsl.Entity{
  name: :statement,
  describe: """
  Add a custom statement for migrations.
  """,
  examples: [
    """
    statement :pgweb_idx do
      up "CREATE INDEX pgweb_idx ON pgweb USING GIN (to_tsvector('english', title || ' ' || body));"
      down "DROP INDEX pgweb_idx;"
    end
    """
  ],
  target: AshPostgres.Statement,
  schema: AshPostgres.Statement.schema(),
  args: [:name]
}

@custom_statements %Spark.Dsl.Section{
  name: :custom_statements,
  describe: """
  A section for configuring custom statements to be added to migrations.

    default: true,
    doc: "Whether or not the resource base filter should be included in the index predicate."
  ]
]

def schema, do: @schema

def column_name(field) when is_atom(field) or is_binary(field), do: field

def column_name({order, field})
    when order in [:asc, :desc] and (is_atom(field) or is_binary(field)),
    do: field

def field_to_snapshot(field) when is_atom(field), do: %{type: "atom", value: field}
def field_to_snapshot(field) when is_binary(field), do: %{type: "string", value: field}

def field_to_snapshot({order, field})
    when order in [:asc, :desc] and (is_atom(field) or is_binary(field)) do
  %{
    type: "directed",
    order: to_string(order),
    value: if(is_atom(field), do: to_string(field), else: field)
  }
end

def field_comparison_key(field) when is_atom(field), do: to_string(field)
def field_comparison_key(field) when is_binary(field), do: field

def field_comparison_key({order, field})
    when order in [:asc, :desc] and (is_atom(field) or is_binary(field)) do
  "#{order}:#{field}"
